const lv_image_dsc_t *qweather_icon_get(const char *code)
{
    if (code == NULL) {
        return NULL;
    }
    for (size_t i = 0; i < sizeof(s_qw_map) / sizeof(s_qw_map[0]); i++) {
        if (strcmp(code, s_qw_map[i].code) == 0) {
            return s_qw_map[i].icon;
        }
    }
    return NULL;
}
